create table "air_riddle" ("id" uuid not null default gen_random_uuid(), "player_id" varchar(255) not null, "player_name" varchar(255) not null, "created_at" timestamptz not null default now(), primary key ("id"));
create table "bracket_link" ("id" varchar(255) not null, "match_id" varchar(255) not null, "previous_match_id" varchar(255) not null, "type" varchar(255) not null, primary key ("id"));
create table "contract" ("id" uuid not null default gen_random_uuid(), "player_id" uuid not null, "team_id" uuid not null, "start_date" date not null, "end_date" date null, "role" text not null default 'active', "created_at" timestamptz not null default now(), primary key ("id"));
create table "image" ("id" uuid not null default gen_random_uuid(), "image_id" varchar(255) not null, "url" varchar(500) not null, "created_at" timestamptz not null, primary key ("id"));
create table "league" ("id" varchar(255) not null, "pandascore_id" int not null, "name" varchar(255) not null, "slug" varchar(255) null, "url" varchar(255) null, "image_url" varchar(255) null, "modified_at" timestamptz null, "created_at" timestamptz not null, "updated_at" timestamptz not null, primary key ("id"));
create table "match_participants" ("match_id" varchar(255) not null, "tournament_participant_id" varchar(255) not null, primary key ("match_id", "tournament_participant_id"));
create table "match_result" ("id" varchar(255) not null, "match_id" varchar(255) not null, "participant_id" varchar(255) not null, "score" int not null, primary key ("id"));
create table "match" ("id" varchar(255) not null, "pandascore_id" int null, "name" varchar(255) not null, "slug" varchar(255) null, "begin_at" timestamptz null, "end_at" timestamptz null, "status" varchar(255) null, "winner_id" varchar(255) null, "number_of_games" int null, "official_streams" jsonb not null default '[]', "created_at" timestamptz not null, "updated_at" timestamptz not null, "tournament_id" varchar(255) not null, primary key ("id"));
create table "news_article" ("id" uuid not null default gen_random_uuid(), "slug" varchar(255) not null, "title" varchar(255) not null, "content" text not null, "title_fr" varchar(255) null, "content_fr" text null, "author_id" uuid not null, "created_at" timestamptz not null, "updated_at" timestamptz null, "is_draft" boolean not null default true, "image_url" varchar(255) null, "type" text not null default 'short', primary key ("id"));
create table "personal_access_token" ("id" uuid not null default gen_random_uuid(), "owner_id" uuid not null, "name" varchar(255) not null, "token_hash" varchar(255) not null, "created_at" timestamptz not null default now(), "last_used_at" timestamptz null, "revoked_at" timestamptz null, primary key ("id"));
create table "pickem_choice" ("id" varchar(255) not null, "user_id" uuid not null, "match_id" varchar(255) not null, "picked_participant_id" varchar(255) not null, "points" int null, "scored" boolean not null default false, "created_at" timestamptz not null, primary key ("id"));
create table "player_award" ("id" uuid not null default gen_random_uuid(), "tournament_id" varchar(255) not null, "participant_id" varchar(255) not null, "player_id" uuid not null, "award_type" text not null, "created_at" timestamptz not null default now(), primary key ("id"));
create table "player_photo" ("id" uuid not null default gen_random_uuid(), "player_id" uuid not null, "url" varchar(255) not null, "created_at" timestamptz not null default now(), primary key ("id"));
create table "player" ("id" uuid not null default gen_random_uuid(), "name" varchar(255) not null, "team_id" uuid null, "birthday" date null, "nationality" varchar(255) null, "first_name" varchar(255) null, "last_name" varchar(255) null, "image_url" varchar(255) null, "role" varchar(255) null, "slug" varchar(255) not null, "pandascore_id" int null, primary key ("id"));
create table "post_translation" ("id" uuid not null default gen_random_uuid(), "post_id" uuid not null, "locale" varchar(255) not null, "title" varchar(255) not null, "content" text not null, "created_at" timestamptz not null, "updated_at" timestamptz null, primary key ("id"));
create table "post" ("id" uuid not null default gen_random_uuid(), "title" varchar(255) not null, "content" text not null, "topic_id" uuid not null, "author_id" uuid not null, "post_type" text not null default 'DISCUSSION', "created_at" timestamptz not null, "updated_at" timestamptz null, primary key ("id"));
create table "reply_notification" ("id" uuid not null default gen_random_uuid(), "recipient_id" uuid not null, "reply_id" uuid not null, "read_at" timestamptz null, "created_at" timestamptz not null, primary key ("id"));
create table "reply_report" ("id" uuid not null default gen_random_uuid(), "reply_id" uuid not null, "reporter_id" uuid not null, "reason" varchar(255) not null, "created_at" timestamptz not null, primary key ("id"));
create table "reply" ("id" uuid not null default gen_random_uuid(), "content" text not null, "created_at" timestamptz not null, "author_id" uuid not null, "post_id" uuid null, "news_article_id" uuid null, "match_id" varchar(255) null, "reply_to_id" uuid null, "hidden_at" timestamptz null, primary key ("id"));
create table "team" ("id" uuid not null default gen_random_uuid(), "name" varchar(255) not null, "location" varchar(255) null, "image_url" varchar(255) null, "dark_mode_image_url" varchar(255) null, "slug" varchar(255) not null, "pandascore_id" int null, primary key ("id"));
create table "topic" ("id" uuid not null default gen_random_uuid(), "title" varchar(255) not null, "description" text null, "created_at" timestamptz not null, "updated_at" timestamptz null, primary key ("id"));
create table "tournament_participant_players" ("tournament_participant_id" varchar(255) not null, "player_id" uuid not null, primary key ("tournament_participant_id", "player_id"));
create table "tournament_participant" ("id" varchar(255) not null, "tournament_id" varchar(255) not null, "team_id" uuid not null, "created_at" timestamptz not null, "updated_at" timestamptz not null, primary key ("id"));
create table "tournament" ("id" varchar(255) not null, "pandascore_id" int null, "source" varchar(255) not null default 'pandascore', "name" varchar(255) not null, "description" varchar(255) null, "slug" varchar(255) null, "serie" varchar(255) null, "tier" varchar(255) null, "begin_at" timestamptz null, "end_at" timestamptz null, "winner_id" varchar(255) null, "winner_type" varchar(255) null, "type" varchar(255) null, "country" varchar(255) null, "prizepool" varchar(255) null, "image_url" varchar(255) null, "league_id" varchar(255) null, "pickems_enabled" boolean not null default false, "has_bracket" boolean not null default false, "created_at" timestamptz not null, "updated_at" timestamptz not null, primary key ("id"));
create table "user" ("id" uuid not null default gen_random_uuid(), "role" varchar(255) null, "email" varchar(255) not null, "user_name" varchar(255) not null, "password" varchar(255) null, "avatar_url" varchar(255) null, "created_at" timestamptz not null default now(), "google_id" varchar(255) null, primary key ("id"));
set names 'utf8';
